def match(orders):
    trades = []
    buy_book = []  # (price, arrival_time, id, qty) - sorted by (-price, arrival_time)
    sell_book = []  # (price, arrival_time, id, qty) - sorted by (price, arrival_time)
    order_map = {}  # id -> {'side': ..., 'original_qty': ..., 'filled_qty': ..., 'arrival_time': ...}
    arrival_time = 0

    def add_to_buy_book(price, order_id, qty, arr_time):
        buy_book.append((price, arr_time, order_id, qty))
        buy_book.sort(key=lambda x: (-x[0], x[1]))

    def add_to_sell_book(price, order_id, qty, arr_time):
        sell_book.append((price, arr_time, order_id, qty))
        sell_book.sort(key=lambda x: (x[0], x[1]))

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                info = order_map[order_id]
                if info['filled_qty'] < info['original_qty']:
                    # Remove from book
                    if info['side'] == 'buy':
                        buy_book[:] = [o for o in buy_book if o[2] != order_id]
                    else:
                        sell_book[:] = [o for o in sell_book if o[2] != order_id]
                    del order_map[order_id]
            arrival_time += 1
            continue

        order_type = order[0]
        order_id = order[1]
        side = order[2]

        if order_type == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        order_map[order_id] = {
            'side': side,
            'original_qty': qty,
            'filled_qty': 0,
            'arrival_time': arrival_time
        }

        remaining_qty = qty

        if side == 'buy':
            # Match against sell_book (lowest price first, then earliest arrival)
            i = 0
            while i < len(sell_book) and remaining_qty > 0:
                sell_price, sell_time, sell_id, sell_qty = sell_book[i]

                if order_type == 'market' or price >= sell_price:
                    trade_qty = min(remaining_qty, sell_qty)
                    trades.append([order_id, sell_id, sell_price, trade_qty])

                    remaining_qty -= trade_qty
                    order_map[order_id]['filled_qty'] += trade_qty
                    order_map[sell_id]['filled_qty'] += trade_qty

                    if sell_qty > trade_qty:
                        sell_book[i] = (sell_price, sell_time, sell_id, sell_qty - trade_qty)
                        i += 1
                    else:
                        sell_book.pop(i)
                else:
                    break
        else:  # sell
            # Match against buy_book (highest price first, then earliest arrival)
            i = 0
            while i < len(buy_book) and remaining_qty > 0:
                buy_price, buy_time, buy_id, buy_qty = buy_book[i]

                if order_type == 'market' or price <= buy_price:
                    trade_qty = min(remaining_qty, buy_qty)
                    trades.append([buy_id, order_id, buy_price, trade_qty])

                    remaining_qty -= trade_qty
                    order_map[order_id]['filled_qty'] += trade_qty
                    order_map[buy_id]['filled_qty'] += trade_qty

                    if buy_qty > trade_qty:
                        buy_book[i] = (buy_price, buy_time, buy_id, buy_qty - trade_qty)
                        i += 1
                    else:
                        buy_book.pop(i)
                else:
                    break

        # Add remaining to book (only for limit orders)
        if remaining_qty > 0 and order_type == 'limit':
            if side == 'buy':
                add_to_buy_book(price, order_id, remaining_qty, arrival_time)
            else:
                add_to_sell_book(price, order_id, remaining_qty, arrival_time)

        arrival_time += 1

    return trades

